  1	package app
  2	
  3	import (
  4		"context"
  5		"crypto/sha256"
  6		"errors"
  7		"fmt"
  8		"image"
  9		_ "image/gif"
 10		_ "image/jpeg"
 11		_ "image/png"
 12		"io"
 13		"mime/multipart"
 14		"net/http"
 15		"os"
 16		"path/filepath"
 17		"strconv"
 18		"strings"
 19		"syscall"
 20		"time"
 21	)
 22	
 23	// Screen captures attached to a report become their own slides in the exported
 24	// deck, either before or after the written content.
 25	
 26	// stateDirectoryAttachments is resolved at startup like the other state paths.
 27	var stateDirectoryAttachments = stateDirectory + "/attachments"
 28	
 29	const (
 30		placementBefore = "BEFORE"
 31		placementAfter  = "AFTER"
 32	)
 33	
 34	// imageFormats maps the formats decoded by the standard library to the parts a
 35	// PPTX package needs. Anything else is rejected rather than trusted.
 36	var imageFormats = map[string]struct{ ContentType, Extension string }{
 37		"png":  {"image/png", "png"},
 38		"jpeg": {"image/jpeg", "jpeg"},
 39		"gif":  {"image/gif", "gif"},
 40	}
 41	
 42	type attachmentView struct {
 43		ID        int64     `json:"id"`
 44		Filename  string    `json:"filename"`
 45		Caption   string    `json:"caption"`
 46		Placement string    `json:"placement"`
 47		SortOrder int       `json:"sortOrder"`
 48		SizeBytes int64     `json:"sizeBytes"`
 49		Width     int       `json:"width"`
 50		Height    int       `json:"height"`
 51		CreatedAt time.Time `json:"createdAt"`
 52		// Available reports whether the stored file is still readable. A row can
 53		// outlive its file: the images live on the state volume while the rows live
 54		// in PostgreSQL, so a deployment that upgrades without mounting
 55		// /var/lib/weekly keeps every row and loses every file. Saying so here lets
 56		// the screen explain the gap instead of showing a broken image.
 57		Available bool `json:"available"`
 58	}
 59	
 60	type storedAttachment struct {
 61		attachmentView
 62		StoredPath  string
 63		ContentType string
 64		Extension   string
 65	}
 66	
 67	func (a *App) attachmentLimits(ctx context.Context) (maxPerReport int, maxBytes int64) {
 68		maxPerReport = a.settingInt(ctx, "attachment.max_per_report", 20)
 69		if maxPerReport < 1 || maxPerReport > 100 {
 70			maxPerReport = 20
 71		}
 72		megabytes := a.settingInt(ctx, "attachment.max_file_mb", 10)
 73		if megabytes < 1 || megabytes > 50 {
 74			megabytes = 10
 75		}
 76		return maxPerReport, int64(megabytes) << 20
 77	}
 78	
 79	// reportOwner returns the owner of a report, or an error when it is missing.
 80	func (a *App) reportOwner(ctx context.Context, id int64) (int64, error) {
 81		var owner int64
 82		if err := a.db.QueryRow(ctx, `SELECT user_id FROM weekly_reports WHERE id=$1`, id).Scan(&owner); err != nil {
 83			return 0, errNotFound
 84		}
 85		return owner, nil
 86	}
 87	
 88	func (a *App) listAttachments(w http.ResponseWriter, r *http.Request) {
 89		id, ok := pathID(w, r)
 90		if !ok {
 91			return
 92		}
 93		p := currentPrincipal(r.Context())
 94		if !a.canViewReport(r.Context(), p, id) {
 95			writeError(w, http.StatusForbidden, "FORBIDDEN", "이 보고서의 첨부 이미지를 조회할 권한이 없습니다.")
 96			return
 97		}
 98		items, err := a.loadAttachments(r.Context(), id)
 99		if err != nil {
100			a.logger.Error("list attachments", "error", err, "reportId", id)
101			writeError(w, http.StatusInternalServerError, "QUERY_FAILED", "첨부 이미지를 조회할 수 없습니다.")
102			return
103		}
104		result := make([]attachmentView, 0, len(items))
105		for _, item := range items {
106			result = append(result, item.attachmentView)
107		}
108		writeData(w, http.StatusOK, result)
109	}
