112		rows, err := a.db.Query(ctx, `SELECT id,original_filename,caption,placement,sort_order,size_bytes,width,height,created_at,stored_path,content_type,extension
113			FROM report_attachments WHERE report_id=$1
114			ORDER BY CASE placement WHEN 'BEFORE' THEN 0 ELSE 1 END, sort_order, id`, reportID)
115		if err != nil {
116			return nil, err
117		}
118		defer rows.Close()
119		result := []storedAttachment{}
120		for rows.Next() {
121			var item storedAttachment
122			if err := rows.Scan(&item.ID, &item.Filename, &item.Caption, &item.Placement, &item.SortOrder,
123				&item.SizeBytes, &item.Width, &item.Height, &item.CreatedAt,
124				&item.StoredPath, &item.ContentType, &item.Extension); err != nil {
125				return nil, err
126			}
127			_, statErr := os.Stat(safeAttachmentPath(item.StoredPath))
128			item.Available = statErr == nil
129			result = append(result, item)
130		}
131		return result, rows.Err()
