134	// checkAttachmentIntegrity reports rows whose image file is gone.
135	//
136	// It runs at start-up because the usual cause is a deployment mistake that is
137	// invisible until someone opens an old report: the state volume was not
138	// mounted, so the files are gone while every row survived in PostgreSQL. A 404
139	// on one image is a puzzle; this line in the boot log is an answer.
140	func (a *App) checkAttachmentIntegrity(ctx context.Context) {
141		rows, err := a.db.Query(ctx, `SELECT stored_path FROM report_attachments`)
142		if err != nil {
143			return
144		}
145		defer rows.Close()
146		total, missing := 0, 0
147		for rows.Next() {
148			var storedPath string
149			if err := rows.Scan(&storedPath); err != nil {
150				return
151			}
152			total++
153			if _, statErr := os.Stat(safeAttachmentPath(storedPath)); statErr != nil {
154				missing++
155			}
156		}
157		if rows.Err() != nil || total == 0 {
158			return
159		}
160		if missing == 0 {
161			a.logger.Info("attachment files verified", "attachments", total)
162			return
163		}
164		a.logger.Warn("attachment files are missing; captures will not display or export",
165			"missing", missing, "attachments", total, "directory", stateDirectoryAttachments,
166			"hint", "확인: /var/lib/weekly 를 영속 볼륨으로 마운트했는지. 파일이 유실된 첨부는 다시 업로드해야 합니다.")
167	}
