337	// checkedAttachment is one uploaded image that has passed every check the
338	// request can be refused on. Its bytes are deliberately not kept — see the
339	// second pass in uploadAttachments.
340	type checkedAttachment struct {
341		header      *multipart.FileHeader
342		contentType string
343		extension   string
344		sum         string
345		relative    string
346		width       int
347		height      int
348	}
349	
350	// readUploadedImage reads one part whole, or names the refusal it earns. The
351	// read is capped one byte past the administrator's per-file limit, which is
352	// enough to know the file is over it.
353	func readUploadedImage(header *multipart.FileHeader, maxBytes int64) (body []byte, code, message string) {
354		if header.Size > maxBytes {
355			return nil, "FILE_TOO_LARGE",
356				fmt.Sprintf("%s의 크기가 허용 한도(%dMB)를 초과했습니다.", header.Filename, maxBytes>>20)
357		}
358		stream, openErr := header.Open()
359		if openErr != nil {
360			return nil, "INVALID_UPLOAD", "업로드한 파일을 읽을 수 없습니다."
361		}
362		defer stream.Close()
363		body, readErr := io.ReadAll(io.LimitReader(stream, maxBytes+1))
364		if readErr != nil || int64(len(body)) > maxBytes {
365			return nil, "FILE_TOO_LARGE", "업로드한 파일이 너무 큽니다."
366		}
367		return body, "", ""
368	}
