371	func (a *App) serveAttachment(w http.ResponseWriter, r *http.Request) {
372		reportID, attachmentID, ok := attachmentPathIDs(w, r)
373		if !ok {
374			return
375		}
376		if !a.canViewReport(r.Context(), currentPrincipal(r.Context()), reportID) {
377			writeError(w, http.StatusForbidden, "FORBIDDEN", "이 이미지를 조회할 권한이 없습니다.")
378			return
379		}
380		var storedPath, contentType string
381		err := a.db.QueryRow(r.Context(), `SELECT stored_path,content_type FROM report_attachments WHERE id=$1 AND report_id=$2`,
382			attachmentID, reportID).Scan(&storedPath, &contentType)
383		if err != nil {
384			writeError(w, http.StatusNotFound, "ATTACHMENT_NOT_FOUND", "첨부 이미지를 찾을 수 없습니다.")
385			return
386		}
387		body, err := os.ReadFile(safeAttachmentPath(storedPath))
388		if err != nil {
389			// A distinct code, because the two 404s here have different causes and
390			// different fixes: no row means a stale link, a missing file means the
391			// stored image is gone and has to be attached again.
392			a.logger.Error("read attachment", "error", err, "attachmentId", attachmentID, "storedPath", storedPath)
393			writeError(w, http.StatusNotFound, "ATTACHMENT_FILE_MISSING",
394				"첨부 이미지 파일이 서버에 없습니다. 이미지를 다시 첨부해 주세요.")
395			return
396		}
397		w.Header().Set("Content-Type", contentType)
398		w.Header().Set("Content-Length", fmt.Sprint(len(body)))
399		w.Header().Set("Cache-Control", "private, max-age=300")
400		w.Header().Set("Content-Disposition", "inline")
401		_, _ = w.Write(body)
402	}
