func samplePNG(t *testing.T, width, height int) []byte {
	t.Helper()
	canvas := image.NewRGBA(image.Rect(0, 0, width, height))
	for x := 0; x < width; x++ {
		for y := 0; y < height; y++ {
			canvas.Set(x, y, color.RGBA{R: uint8(x % 255), G: uint8(y % 255), B: 120, A: 255})
		}
	}
	var buffer bytes.Buffer
	if err := png.Encode(&buffer, canvas); err != nil {
		t.Fatal(err)
	}
	return buffer.Bytes()
}

func captureAttachment(id int64, name, caption, placement string, width, height int) storedAttachment {
	item := storedAttachment{ContentType: "image/png", Extension: "png", StoredPath: name}
	item.ID = id
	item.Filename = name
	item.Caption = caption
	item.Placement = placement
	item.Width = width
	item.Height = height
	}
	// A capture that changes sides takes the end of the side it arrives on.
	// Writing placement alone left sort_order as it was, while the upload route
	// numbers a new image coalesce(max(sort_order),-1)+1 *within its placement*
	// — so the number that left one group was handed out again inside it, and
	// the capture carrying it back collided with a row already sitting in the
	// destination. Two rows sharing one sort_order are ordered by id instead of
	// by what the writer chose, in the list and in the exported deck, and the
	// panel's up/down buttons swap the two sort_orders, which with equal values
	// changes nothing — so the writer could not correct it either.
	//
	// The subquery is the same expression the upload route counts with, so both
	// entrances read one group's end the same way. One statement, so there is no
	// second round trip and nothing to race: PostgreSQL evaluates every SET
	// expression — the subquery included — against the row and the snapshot as
	// they were before the update, which is why the moving row is still counted
	// in its old group rather than in the one it is being counted into. A sent
	// sortOrder is the caller stating a position and still wins, and a placement
	// equal to the current one is not a move.
	command, err := a.db.Exec(r.Context(), `UPDATE report_attachments SET
		caption=coalesce($1,caption),
		placement=coalesce($2::text,placement),
		sort_order=CASE
			WHEN $3::int IS NOT NULL THEN $3::int
			WHEN $2::text IS NOT NULL AND $2::text <> placement THEN
				(SELECT coalesce(max(peer.sort_order),-1)+1 FROM report_attachments peer
					WHERE peer.report_id=$5::bigint AND peer.placement=$2::text)
			ELSE sort_order
		END
		WHERE id=$4::bigint AND report_id=$5::bigint`,
		input.Caption, nullableString(placement), input.SortOrder, attachmentID, reportID)
	if err != nil {
		a.logger.Error("update attachment", "error", err, "attachmentId", attachmentID, "trace", traceIDFromContext(r.Context()))
		writeError(w, http.StatusInternalServerError, "DATABASE_ERROR", "이미지 정보를 저장할 수 없습니다.")
		return
	}
	if command.RowsAffected() == 0 {
		writeError(w, http.StatusNotFound, "ATTACHMENT_NOT_FOUND", "첨부 이미지를 찾을 수 없습니다.")
		return
	}
	writeData(w, http.StatusOK, map[string]int64{"id": attachmentID})
}

func (a *App) deleteAttachment(w http.ResponseWriter, r *http.Request) {
	reportID, attachmentID, ok := attachmentPathIDs(w, r)
	if !ok {
		return
	}
	p := currentPrincipal(r.Context())
	owner, err := a.reportOwner(r.Context(), reportID)
	if err != nil || owner != p.ID {
		writeError(w, http.StatusForbidden, "FORBIDDEN", "본인의 보고서 이미지만 삭제할 수 있습니다.")
		return
	}
	var storedPath string
	err = a.db.QueryRow(r.Context(), `DELETE FROM report_attachments WHERE id=$1 AND report_id=$2 RETURNING stored_path`,
		attachmentID, reportID).Scan(&storedPath)
	if err != nil {
		writeError(w, http.StatusNotFound, "ATTACHMENT_NOT_FOUND", "첨부 이미지를 찾을 수 없습니다.")
		return
	}
	// The same bytes can back two rows after a duplicate upload, so only remove
	// the file once nothing references it any more.
	var remaining int
	_ = a.db.QueryRow(r.Context(), `SELECT count(*) FROM report_attachments WHERE stored_path=$1`, storedPath).Scan(&remaining)
	if remaining == 0 {
		if err := os.Remove(safeAttachmentPath(storedPath)); err != nil && !errors.Is(err, os.ErrNotExist) {
			a.logger.Warn("remove attachment file", "error", err, "attachmentId", attachmentID)
		}
	}
	a.audit(r, p, "report.attachment_delete", "report", strconv.FormatInt(reportID, 10), map[string]any{"attachmentId": attachmentID})
	w.WriteHeader(http.StatusNoContent)
}

func attachmentPathIDs(w http.ResponseWriter, r *http.Request) (int64, int64, bool) {
	reportID, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || reportID <= 0 {
		writeError(w, http.StatusBadRequest, "INVALID_ID", "보고서 식별자가 올바르지 않습니다.")
		return 0, 0, false
	}
	attachmentID, err := strconv.ParseInt(r.PathValue("attachmentId"), 10, 64)
	if err != nil || attachmentID <= 0 {
		writeError(w, http.StatusBadRequest, "INVALID_ID", "이미지 식별자가 올바르지 않습니다.")
		return 0, 0, false
	}
	return reportID, attachmentID, true
}

// safeAttachmentPath keeps a stored path inside the attachment directory even if
// the column were ever tampered with.
func safeAttachmentPath(stored string) string {
	clean := filepath.Clean("/" + strings.ReplaceAll(stored, `\`, "/"))
	return filepath.Join(stateDirectoryAttachments, filepath.FromSlash(clean))
}
